The partial fraction decomposition of
\[\frac{x^2 - 19}{x^3 - 2x^2 - 5x + 6}\]is
\[\frac{A}{x - 1} + \frac{B}{x + 2} + \frac{C}{x - 3}.\]Find the product $ABC.$

Put your final answer within \boxed{}.

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // Define the coefficients of the polynomial
    vector<int> coefficients = {1, -2, -5, 6};

    // Find the roots of the polynomial
    vector<int> roots;
    for (int i = 0; i < coefficients.size(); i++) {
        if (coefficients[i] == 0) {
            roots.push_back(coefficients[i + 1]);
        }
    }

    // Compute the partial fraction decomposition
    vector<int> partial_fractions;
    for (int root : roots) {
        partial_fractions.push_back(1 / (root - 1));
        partial_fractions.push_back(1 / (root + 2));
        partial_fractions.push_back(1 / (root - 3));
    }

    // Compute the product of the partial fractions
    int product = 1;
    for (int partial_fraction : partial_fractions) {
        product *= partial_fraction;
    }

    // Print the product
    cout << product << endl;

    return 0;
}

