    int n = 3;
    vector<int> coefficients(n + 1, 0);
    coefficients[0] = 1;
    coefficients[1] = 2;
    coefficients[2] = 5;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
