Put your final answer within \boxed{}.

#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

int main() {
    int n = 12;
    int k = 70;
    vector<int> coefficients(n + 1, 0);
    coefficients[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = i; j >= 1; j--) {
            coefficients[j] += coefficients[j - 1];
        }
    }
    int result = 0;
    for (int i = 0; i <= n; i++) {
        if (i * (n - i) == k) {
            result = coefficients[i];
        }
    }
    cout << "The coefficient of x^" << k << " is " << result << endl;
    return 0;
}

